def clone_graph(node):
    if node is None:
        return None
    old_to_new = {}
    def dfs(n):
        if n in old_to_new:
            return old_to_new[n]                              # REUSE the existing clone
        clone = Node(n.val)
        old_to_new[n] = clone                                    # store BEFORE recursing (breaks cycles)
        for neighbor in n.neighbors:
            clone.neighbors.append(dfs(neighbor))
        return clone
    return dfs(node)

