import java.util.*;

public class Main {
    static Map<Node, Node> oldToNew = new HashMap<>();

    static Node cloneGraph(Node node) {
        if (node == null) return null;
        oldToNew.clear();
        return dfs(node);
    }

    static Node dfs(Node n) {
        if (oldToNew.containsKey(n)) return oldToNew.get(n);           // REUSE the existing clone
        Node clone = new Node(n.val);
        oldToNew.put(n, clone);                                          // store BEFORE recursing (breaks cycles)
        for (Node neighbor : n.neighbors) {
            clone.neighbors.add(dfs(neighbor));
        }
        return clone;
    }
}

